$ErrorActionPreference='Stop';$run='C:\Users\aaron\Desktop\URAP\artifacts\detached_tvd_detector_hard_replay_v165';if(!(Test-Path "$run\pid.txt")){Write-Host 'NOT RUNNING: PID file missing';exit 1};$pidValue=[int](Get-Content "$run\pid.txt");$meta=Get-Content "$run\meta.json" -Raw|ConvertFrom-Json;$proc=Get-CimInstance Win32_Process -Filter "ProcessId=$pidValue" -ErrorAction SilentlyContinue;if($proc){Write-Host "RUNNING PID: $pidValue";Write-Host "Command: $($proc.CommandLine)"}else{Write-Host "NOT RUNNING PID: $pidValue"};Write-Host "Start time: $($meta.start_time)";Write-Host "Stdout log: $($meta.stdout_log)";Write-Host "Stderr log: $($meta.stderr_log)";$done=0;if(Test-Path $meta.results_csv){$done=[Math]::Max(0,(Get-Content $meta.results_csv|Measure-Object -Line).Lines-1)};Write-Host "Epochs: $done/$($meta.expected_epochs)";$log=Get-Content $meta.stderr_log -Raw -ErrorAction SilentlyContinue;$matches=[regex]::Matches($log,'(\d+)/(\d+) \[');if($matches.Count){$last=$matches[$matches.Count-1];Write-Host "Last completed unit: batch $($last.Groups[1].Value)/$($last.Groups[2].Value)"}else{Write-Host 'Last completed unit: initialization'};Write-Host "Last output: $((Get-Item $meta.stderr_log).LastWriteTime.ToString('o'))";nvidia-smi --query-gpu=timestamp,utilization.gpu,memory.used,memory.total --format=csv,noheader
